// femacs: port of src/lread.c @ fd7afced403.
//
// One-to-one port (PORTING.md): same statements in the same order, same names (function,
// macro, struct/union/struct field, file-scope object, local), same control flow, same
// error model.  The 17 `DEFUN`s use `DEFUN!` (PORTING.md 5.1); this unit is the reader, so
// `read0`/`read1`'s dispatch, `oblookup` and the interned-symbol handling keep C's shape.
//
// **Carried arms (docs/status.md 3.49, PORTING.md P-51).**  `src/lread.c` is *not* in
// `docs/baseline/config/cond-eval-verified.txt`, so `tools/extract-abi.py`'s
// `blind_conditions` keeps *both* arms of every `#if` live and the per-function token
// check demands the tokens of C's text on both sides.  Per the integrator's 2026-10-03
// decision the port therefore *carries* the arms the frozen build does not compile, each
// under a `#[cfg (feature = "…")]` naming the C condition's non-frozen side (the
// `timefns.rs`/`callproc.rs`/`print.rs` shape).  The arms, in C order, are listed in
// `docs/ports/lread.md`'s Decisions section.
//
// **`IEEE_FLOATING_POINT`** is the one *source-header* macro among the conditions
// (`lisp.h` 3201-3202 computes it from `<float.h>`, which `config.h`'s dump cannot see);
// the row `lisp.h\tIEEE_FLOATING_POINT` in `docs/baseline/config/source-header-macros.tsv`
// records clang's frozen value for it (step 5 of the per-file loop), so the evaluator now
// agrees with clang (`check-cond-eval.py src/lread.c` -> `39 conditions, 0 unknown,
// 0 disagreements`).  The file still stays out of the verified list on purpose: carrying
// both arms is the stricter comparison (docs/status.md 3.51, the callproc.rs precedent).

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code,
         unused_imports, unused_macros, unused_variables, unused_unsafe, static_mut_refs,
         unsafe_op_in_unsafe_fn, unused_assignments, unreachable_code, while_true,
         unused_parens, unused_mut, clashing_extern_declarations)]

include!("include/config.rs");                 // C 24: `#include <config.h>`
