/* ---- Names no mirror carries, declared at their use site (PORTING.md 0.1-2/P-72).
   `<sys/file.h>` (C 29) has no mirror: it contributes `O_RDONLY` (fcntl.rs) and nothing the
   port names.  `<locale.h>` (C 31) is included only for `Vlocale_coding_system`'s
   `LC_*`/`setlocale` machinery, which `dir_warning` does not name.  `<epaths.h>` (C 40) is
   generated by the frozen build; its values are the measured constants below.  The
   `MSDOS`/`HAVE_NS` include pair (C 49-55) has no mirror either and no live name.  */

