#[unsafe(no_mangle)]
pub unsafe extern "C" fn init_obarray_once ()
{
  Vobarray = make_obarray (15);
  initial_obarray = Vobarray;
  staticpro (&raw mut initial_obarray);

  /* C: `for (int i = 0; i < countof (lispsym); i++)` — the port's symbol set is the
     2118-symbol superset (P-29), so the bound is `lispsym_count`.  */
  let mut i: usize = 0;
  while i < lispsym_count
    {
      define_symbol (builtin_lisp_symbol (i), defsym_name[i]);
      i += 1;
    }

  DEFSYM! (Qunbound, "unbound");

  DEFSYM! (Qnil, "nil");
  SET_SYMBOL_VAL (XBARE_SYMBOL (Qnil ()), Qnil ());
  make_symbol_constant (Qnil ());
  set_symbol_bits! (declared_special, XBARE_SYMBOL (Qnil ()), true);

  DEFSYM! (Qt, "t");
  SET_SYMBOL_VAL (XBARE_SYMBOL (Qt ()), Qt ());
  make_symbol_constant (Qt ());
  set_symbol_bits! (declared_special, XBARE_SYMBOL (Qt ()), true);

  /* Qt is correct even if not dumping.  loadup.el will set to nil at end.  */
  Vpurify_flag = Qt ();

  DEFSYM! (Qvariable_documentation, "variable-documentation");
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn defsubr (aname: *mut Aligned_Lisp_Subr)
{
  let sname: *mut Lisp_Subr = &mut (*aname).s;
  let sym: Lisp_Object;
  let mut tem: Lisp_Object;
  sym = intern_c_string ((*sname).symbol_name);
  XSETPVECTYPE! (sname, pvec_type::PVEC_SUBR);
  XSETSUBR! (tem, sname);
  set_symbol_function (sym, tem);
  #[cfg (feature = "have_native_comp")]
  {
    eassert! (NILP (Vcomp_abi_hash));
    Vcomp_subr_list = Fcons (tem, Vcomp_subr_list);
  }
}

/* Define an "integer variable"; a symbol whose value is forwarded to a
   C variable of type intmax_t.  Sample call (with "xx" to fool make-docfile):
   DEFxxVAR_INT ("emacs-priority", &emacs_priority, "Documentation");  */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn defvar_int (i_fwd: *const Lisp_Fwd, namestring: *const c_char)
{
  eassert! ((*i_fwd).r#type == Lisp_Fwd_Int);
  let sym: Lisp_Object = intern_c_string (namestring);
  set_symbol_bits! (declared_special, XBARE_SYMBOL (sym), true);
  set_symbol_bits! (redirect, XBARE_SYMBOL (sym), SYMBOL_FORWARDED);
  SET_SYMBOL_FWD (XBARE_SYMBOL (sym), i_fwd as *mut c_void);
}

/* Similar but define a variable whose value is t if 1, nil if 0.  */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn defvar_bool (b_fwd: *const Lisp_Fwd, namestring: *const c_char)
{
  eassert! ((*b_fwd).r#type == Lisp_Fwd_Bool);
  let sym: Lisp_Object = intern_c_string (namestring);
  set_symbol_bits! (declared_special, XBARE_SYMBOL (sym), true);
  set_symbol_bits! (redirect, XBARE_SYMBOL (sym), SYMBOL_FORWARDED);
  SET_SYMBOL_FWD (XBARE_SYMBOL (sym), b_fwd as *mut c_void);
  Vbyte_boolean_vars = Fcons (sym, Vbyte_boolean_vars);
}

/* Similar but define a variable whose value is the Lisp Object stored
   at address.  Two versions: with and without gc-marking of the C
   variable.  The nopro version is used when that variable will be
   gc-marked for some other reason, since marking the same slot twice
   can cause trouble with strings.  */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn defvar_lisp_nopro (o_fwd: *const Lisp_Fwd, namestring: *const c_char)
{
  eassert! ((*o_fwd).r#type == Lisp_Fwd_Obj);
  let sym: Lisp_Object = intern_c_string (namestring);
  set_symbol_bits! (declared_special, XBARE_SYMBOL (sym), true);
  set_symbol_bits! (redirect, XBARE_SYMBOL (sym), SYMBOL_FORWARDED);
  SET_SYMBOL_FWD (XBARE_SYMBOL (sym), o_fwd as *mut c_void);
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn defvar_lisp (o_fwd: *const Lisp_Fwd, namestring: *const c_char)
{
  eassert! ((*o_fwd).r#type == Lisp_Fwd_Obj);
  defvar_lisp_nopro (o_fwd, namestring);
  staticpro ((*o_fwd).u.objvar);
}

/* Similar but define a variable whose value is the Lisp Object stored
   at a particular offset in the current kboard object.  */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn defvar_kboard (ko_fwd: *const Lisp_Fwd, namestring: *const c_char)
{
  eassert! ((*ko_fwd).r#type == Lisp_Fwd_Kboard_Obj);
  let sym: Lisp_Object = intern_c_string (namestring);
  set_symbol_bits! (declared_special, XBARE_SYMBOL (sym), true);
  set_symbol_bits! (redirect, XBARE_SYMBOL (sym), SYMBOL_FORWARDED);
  SET_SYMBOL_FWD (XBARE_SYMBOL (sym), ko_fwd as *mut c_void);
}

/* Check that the elements of lpath exist.  */
unsafe fn load_path_check (lpath: Lisp_Object)
{
  let mut path_tail: Lisp_Object;

  /* The only elements that might not exist are those from
     PATH_LOADSEARCH, EMACSLOADPATH.  Anything else is only added if
     it exists.  */
  path_tail = lpath;
  while !NILP (path_tail)
    {
      let mut dirfile: Lisp_Object;
      dirfile = Fcar (path_tail);
      if STRINGP (dirfile)
	{
	  dirfile = Fdirectory_file_name (dirfile);
	  if !file_accessible_directory_p (dirfile)
	    { dir_warning (c"Lisp directory".as_ptr (), XCAR (path_tail)); }
	}
      path_tail = XCDR (path_tail);
    }
}

/* Return the default load-path, to be used if EMACSLOADPATH is unset.  ...  */
unsafe fn load_path_default () -> Lisp_Object
{
  if will_dump_p ()
    /* PATH_DUMPLOADSEARCH is the lisp dir in the source directory.
       We used to add ../lisp (ie the lisp dir in the build
       directory) at the front here, but that should not be
       necessary, since in out of tree builds lisp/ is empty, save
       for Makefile.  */
    { return decode_env_path (0 as *const c_char, PATH_DUMPLOADSEARCH, false); }

  let mut lpath: Lisp_Object = Qnil ();

  lpath = decode_env_path (0 as *const c_char, PATH_LOADSEARCH, false);

  if !NILP (Vinstallation_directory)
    {
      let mut tem: Lisp_Object;
      let mut tem1: Lisp_Object;

      /* Add to the path the lisp subdir of the installation
	 dir, if it is accessible.  Note: in out-of-tree builds,
	 this directory is empty save for Makefile.  */
      tem = Fexpand_file_name (build_string (c"lisp".as_ptr ()),
			       Vinstallation_directory);
      tem1 = Ffile_accessible_directory_p (tem);
      if !NILP (tem1)
	{
	  if NILP (Fmember (tem, lpath))
	    {
	      /* We are running uninstalled.  The default load-path
		 points to the eventual installed lisp directories.
		 We should not use those now, even if they exist,
		 so start over from a clean slate.  */
	      lpath = list1 (tem);
	    }
	}
      else
	/* That dir doesn't exist, so add the build-time
	   Lisp dirs instead.  */
	{
	  let dump_path: Lisp_Object
	    = decode_env_path (0 as *const c_char, PATH_DUMPLOADSEARCH, false);
	  lpath = nconc2 (lpath, dump_path);
	}

      /* Add site-lisp under the installation dir, if it exists.  */
      if !no_site_lisp
	{
	  tem = Fexpand_file_name (build_string (c"site-lisp".as_ptr ()),
				   Vinstallation_directory);
	  tem1 = Ffile_accessible_directory_p (tem);
	  if !NILP (tem1)
	    {
	      if NILP (Fmember (tem, lpath))
		{ lpath = Fcons (tem, lpath); }
	    }
	}

      /* If Emacs was not built in the source directory,
	 and it is run from where it was built, add to load-path
	 the lisp and site-lisp dirs under that directory.  */

      if NILP (Fequal (Vinstallation_directory, Vsource_directory))
	{
	  let mut tem2: Lisp_Object;

	  tem = Fexpand_file_name (build_string (c"src/Makefile".as_ptr ()),
				   Vinstallation_directory);
	  tem1 = Ffile_exists_p (tem);

	  /* Don't be fooled if they moved the entire source tree
	     AFTER dumping Emacs.  If the build directory is indeed
	     different from the source dir, src/Makefile.in and
	     src/Makefile will not be found together.  */
	  tem = Fexpand_file_name (build_string (c"src/Makefile.in".as_ptr ()),
				   Vinstallation_directory);
	  tem2 = Ffile_exists_p (tem);
	  if !NILP (tem1) && NILP (tem2)
	    {
	      tem = Fexpand_file_name (build_string (c"lisp".as_ptr ()),
				       Vsource_directory);

	      if NILP (Fmember (tem, lpath))
		{ lpath = Fcons (tem, lpath); }

	      if !no_site_lisp
		{
		  tem = Fexpand_file_name (build_string (c"site-lisp".as_ptr ()),
					   Vsource_directory);
		  tem1 = Ffile_accessible_directory_p (tem);
		  if !NILP (tem1)
		    {
		      if NILP (Fmember (tem, lpath))
			{ lpath = Fcons (tem, lpath); }
		    }
		}
	    }
	} /* Vinstallation_directory != Vsource_directory */

    } /* if Vinstallation_directory */

  lpath
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn init_lread ()
{
  /* First, set Vload_path.  */

  /* Ignore EMACSLOADPATH when dumping.  */
  let use_loadpath: bool = !will_dump_p ();

  if use_loadpath && !egetenv (c"EMACSLOADPATH".as_ptr ()).is_null ()
    {
      Vload_path = decode_env_path (c"EMACSLOADPATH".as_ptr (), 0 as *const c_char, true);

      /* Check (non-nil) user-supplied elements.  */
      load_path_check (Vload_path);

      /* If no nils in the environment variable, use as-is.
	 Otherwise, replace any nils with the default.  */
      if !NILP (Fmemq (Qnil (), Vload_path))
	{
	  let mut elem: Lisp_Object;
	  let mut elpath: Lisp_Object = Vload_path;
	  let mut default_lpath: Lisp_Object = load_path_default ();

	  /* Check defaults, before adding site-lisp.  */
	  load_path_check (default_lpath);

	  /* Add the site-lisp directories to the front of the default.  */
	  if !no_site_lisp && *PATH_SITELOADSEARCH != 0
	    {
	      let sitelisp: Lisp_Object;
	      sitelisp = decode_env_path (0 as *const c_char, PATH_SITELOADSEARCH, false);
	      if !NILP (sitelisp)
		{ default_lpath = nconc2 (sitelisp, default_lpath); }
	    }

	  Vload_path = Qnil ();

	  /* Replace nils from EMACSLOADPATH by default.  */
	  while CONSP (elpath)
	    {
	      elem = XCAR (elpath);
	      elpath = XCDR (elpath);
	      Vload_path = CALLN! (Fappend, Vload_path,
				   if NILP (elem) { default_lpath } else { list1 (elem) });
	    }
	}                       /* Fmemq (Qnil, Vload_path) */
    }
  else
    {
      Vload_path = load_path_default ();

      /* Check before adding site-lisp directories.
	 The install should have created them, but they are not
	 required, so no need to warn if they are absent.
	 Or we might be running before installation.  */
      load_path_check (Vload_path);

      /* Add the site-lisp directories at the front.  */
      if !will_dump_p () && !no_site_lisp && *PATH_SITELOADSEARCH != 0
	{
	  let sitelisp: Lisp_Object;
	  sitelisp = decode_env_path (0 as *const c_char, PATH_SITELOADSEARCH, false);
	  if !NILP (sitelisp) { Vload_path = nconc2 (sitelisp, Vload_path); }
	}
    }

  Vvalues = Qnil ();

  load_in_progress = false;
  Vload_file_name = Qnil ();
  Vload_true_file_name = Qnil ();
  Vstandard_input = Qt ();
  Vloads_in_progress = Qnil ();
}

/* Print a warning that directory intended for use USE and with name
   DIRNAME cannot be accessed.  On entry, errno should correspond to
   the access failure.  Print the warning on stderr and put it in
   *Messages*.  */
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dir_warning (r#use: *const c_char, dirname: Lisp_Object)
{
  let format: *const c_char = c"Warning: %s '%s': %s\n".as_ptr ();
  let diagnostic: *const c_char = emacs_strerror (*errno ());
  fprintf (stderr, format, r#use, SSDATA (ENCODE_SYSTEM (dirname)), diagnostic);

  /* Don't log the warning before we've initialized!!  */
  if initialized
    {
      let mut diaglen: ptrdiff_t = strlen (diagnostic) as ptrdiff_t;
      AUTO_STRING_WITH_LEN! (diag, diagnostic, diaglen);
      let mut diagnostic: *const c_char = diagnostic;
      if !NILP (Vlocale_coding_system)
	{
	  let s: Lisp_Object
	    = code_convert_string_norecord (diag, Vlocale_coding_system, false);
	  diagnostic = SSDATA (s);
	  diaglen = SBYTES (s);
	}
      USE_SAFE_ALLOCA! (sa_avail, sa_count, sa_mark);
      /* C: `sizeof format - 3 * (sizeof "%s" - 1) + strlen (use) + SBYTES (dirname) + diaglen`
	 — the `sizeof`s of C's `format` (21) and `"%s"` (3), measured with clang.  */
      let buffer: *mut c_char
	= SAFE_ALLOCA! (sa_avail, 21 - 3 * (3 - 1) + strlen (r#use) as ptrdiff_t
			+ SBYTES (dirname) + diaglen) as *mut c_char;
      let message_len: ptrdiff_t = esprintf (buffer, format, r#use, SSDATA (dirname),
					     diagnostic);
      message_dolog (buffer, message_len, false, STRING_MULTIBYTE (dirname));
      SAFE_FREE! (sa_count, sa_mark);
    }
}

/* The `DEFVAR_*` variables this C file owns.  C's storage is `globals.f_<vname>`
   (lisp.h 3495-3530) and `struct emacs_globals globals` is defined once, in alloc.c, so the
   reference object exports `globals` and *no* `V*` symbol for these names; the port gives
   each one its own exported object (docs/status.md 3.29/3.60), because `include/globals.rs`
   mirrors them as *external* declarations and other units read them (`Fload`'s own
   `Vload_path`, `eval-buffer-list`, ...).  `tools/check-symbols.py` counts this class as the
   port's one systematic symbol deviation.  `syms_of_lread` registers them and assigns the
   same initial values C does.  */

